namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0)
            return 0;
        if (attempt > 10)
            return 3600;

        int baseDelay;
        switch (channel)
        {
            case Channel.Email:
                baseDelay = 30;
                break;
            case Channel.Sms:
                baseDelay = 10;
                break;
            case Channel.Push:
                baseDelay = 5;
                break;
            default:
                baseDelay = 15;
                break;
        }

        int delay = baseDelay * attempt;
        if (serverBusy && delay < 600)
            delay *= 2;
        if (delay > 3600)
            delay = 3600;
        else if (delay < 1)
            delay = 1;
        else if (attempt > 7)
            delay += 100;
        return delay;
    }
}

